"""P3 compile matrix for the differential harness (step B2b).

For every corpus row whose input the product accepts, generate the header and
compile it under the supported profiles:

* ``cxx11`` — ``g++ -std=c++11 -pedantic-errors -fsyntax-only``;
* ``cxx17`` — ``g++ -std=c++17 -pedantic-errors -fsyntax-only``;
* ``lite``  — the header generated by the parser-free (descriptor-only) codegen
  build, compiled with both standards; a source row is not applicable to this
  profile because the lite build has no ``.proto`` loader.

The legacy profiles measure the same corpus on an old compiler; they are named
after the compiler that runs them, so the summary cannot be mistaken for the
modern C++11 row:

* ``legacy-gcc47`` — GCC 4.7.3 x64, same C++11 flags (B15, D4-A);
* ``legacy-clang33`` — Clang 3.3 x86, same C++11 flags (B15, D4-A).

A legacy failure is never waivered because the modern row passes; only the
diagnostic-based ``BASELINE_SIGNATURES`` and the default-profile
``KNOWN_P3_ROWS`` table can classify it as known.

A nonzero compile exit is a **P3 verdict**, not a runner error.  The matrix runs
the pinned pre-fix binary, so a failure recorded against a row that the
property catalogue already lists as a P3 violation is a *baseline* failure, not
a new finding.  ``B17`` re-runs the matrix after the fix steps and expects
``unexplained = 0``.

The translation unit includes the generated header.  A generated header is
``#pragma once`` plus inline, non-template definitions, so the include is a
complete semantic check of the declarations *and* the codec bodies; the matrix
deliberately does not invent a C++ expression for every message type.

Dependency headers are generated into the same directory, because the header
contract is "generate the dependencies as well" (``OPTIONS.md``).  A header
whose dependency set cannot be produced is recorded as a setup gap, not as a
compile failure.

Usage:
    python tests/codegen/harness/compile.py --cases 30
    python tests/codegen/harness/compile.py --cases 0 --jobs 8
    python tests/codegen/harness/compile.py --cases 0 \
        --lite-codegen build/b2b-probe/tree-lite/codegen.exe
    python tests/codegen/harness/compile.py --cases 0 \
        --profile legacy-gcc47 --gxx <gcc-4.7>/g++.exe \
        --out tests/codegen/harness/p3-legacy-gcc47.json
"""

from __future__ import annotations

import argparse
import concurrent.futures
import datetime as dt
import json
import os
import pathlib
import platform
import subprocess
import sys
import time

import compare
import fds
import run
import runner

HERE = pathlib.Path(__file__).resolve().parent
REPO = runner.repo_root(HERE)
DEFAULT_GXX = pathlib.Path(os.environ.get("EASYPB_GXX", "g++"))
DEFAULT_PROFILES = ["cxx11", "cxx17"]
PROFILE_FLAGS = {
    "cxx11": ["-std=c++11", "-pedantic-errors", "-fsyntax-only"],
    "cxx17": ["-std=c++17", "-pedantic-errors", "-fsyntax-only"],
    # B15/D4-A: the legacy profiles carry their compiler in the name.  GCC 4.7
    # has no -std=c++14, and Clang 3.3 is the second legacy target; both are
    # measured with the project's C++11 flags.
    "legacy-gcc47": ["-std=c++11", "-pedantic-errors", "-fsyntax-only"],
    "legacy-clang33": ["-std=c++11", "-pedantic-errors", "-fsyntax-only"],
}

# The P3 status block of build/verification/property-catalogue.md.  These rows
# are the measured baseline of the pinned pre-fix binary; B17 owns the final
# verdict after the fix steps.
KNOWN_P3_ROWS = {"CR-02", "CR-03", "CR-04", "CR-05", "CR-08", "CR-09",
                 "CR-10", "CR-43"}


def relative(path: pathlib.Path) -> str:
    return path.resolve().relative_to(REPO).as_posix()


def write_json(path: pathlib.Path, payload: dict) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(
        json.dumps(payload, indent=2, ensure_ascii=True) + "\n",
        encoding="utf-8", newline="\n",
    )


def compiler_first_line(compiler: pathlib.Path, flag: str) -> str | None:
    """Return the first stdout line of ``compiler <flag>``, or None.

    ``--version`` and ``-dumpmachine`` are evidence, not a verdict: a probe
    that fails leaves the field empty and the compile rows still speak.
    """
    try:
        done = subprocess.run([str(compiler), flag], capture_output=True,
                              shell=False, timeout=20)
    except (OSError, subprocess.TimeoutExpired):
        return None
    lines = done.stdout.decode("utf-8", "replace").splitlines()
    return lines[0].strip() if lines else None


def legacy_child_env(compiler: pathlib.Path) -> dict[str, str] | None:
    """Keep the measured tools out of an activated legacy toolchain.

    A GCC 4.7 shell puts ``gcc-4.7-x64\\bin`` first on ``PATH``; that directory
    contains an SJLJ-era x64 ``libstdc++-6.dll`` which shadows the MSYS2 UCRT
    runtime the harness's ``codegen.exe`` was linked against.  The measured
    process then dies with ``0xC0000139`` (entry point not found) before it can
    read its argv, and every row looks like a P1 refusal.  The legacy compiler
    is invoked by absolute path and keeps the activated ``PATH``; only the
    measured ``codegen``/``protoc`` children get this override.
    """
    root = os.path.normcase(str(compiler.resolve().parent.parent).rstrip("\\") + "\\")
    parts = [item for item in os.environ.get("PATH", "").split(os.pathsep) if item]
    kept = [item for item in parts
            if not os.path.normcase(os.path.abspath(item) + "\\").startswith(root)]
    if len(kept) == len(parts):
        return None
    return {"PATH": os.pathsep.join(kept)}


def child_environment(overrides: dict[str, str] | None) -> dict[str, str] | None:
    """Merge overrides onto the current environment for a direct ``run``."""
    if not overrides:
        return None
    env = dict(os.environ)
    env.update(overrides)
    return env


def generate_closure(row: dict, case_dir: pathlib.Path, codegen: pathlib.Path,
                     out_dir: pathlib.Path,
                     env: dict[str, str] | None = None) -> dict:
    """Generate every file of the row's descriptor set into *out_dir*.

    Returns ``{"target": ..., "files": [...], "failures": [...]}``.  The target
    is the row's logical target; a source row that protoc accepted leaves a
    ``source.pbs`` with ``--include_imports``, which is the complete closure.
    """
    out_dir.mkdir(parents=True, exist_ok=True)
    if row["kind"] == "descriptor":
        pbs = REPO / row["input"]
        target = row.get("target")
    else:
        pbs = case_dir / "source.pbs"
        target = None
    info: dict = {"pbs": None, "target": target, "files": [], "failures": []}
    if not pbs.is_file() or pbs.stat().st_size == 0:
        info["failures"].append("no descriptor closure: protoc wrote no set")
        return info
    info["pbs"] = relative(pbs)
    try:
        descriptors = fds.file_descriptors(pbs.read_bytes())
    except fds.WireError as error:
        info["failures"].append("descriptor closure unreadable: %s" % error)
        return info
    names = [item.name for item in descriptors if item.name]
    info["files"] = names
    if target is None:
        target = fds.select_target(descriptors)
    info["target"] = target
    if not target:
        info["failures"].append("descriptor set has no named file")
        return info
    for name in names:
        argv = [
            str(codegen), "--descriptor-set", "--target", name,
            "--out-dir", str(out_dir), str(pbs),
        ]
        done = subprocess.run(argv, capture_output=True, timeout=120,
                              shell=False, cwd=str(case_dir), env=env)
        if done.returncode != 0:
            first = done.stderr.decode("utf-8", "replace").strip().splitlines()
            info["failures"].append("%s: %s" % (
                name, first[0][:200] if first else "rc=%d" % done.returncode))
    return info


def header_for(out_dir: pathlib.Path, target: str) -> pathlib.Path:
    stem = fds.header_stem(target)
    direct = out_dir / (stem + ".pb.hpp")
    if direct.is_file():
        return direct
    matches = sorted(out_dir.rglob(stem + ".pb.hpp"))
    return matches[0] if matches else direct


def kill_process_tree(process: subprocess.Popen) -> None:
    """Terminate a compiler driver and its ``-cc1`` child.

    Clang 3.3's driver re-executes itself as a separate ``-cc1`` process.  On
    Windows that child keeps the inherited stdout/stderr handles open, so a
    plain ``Popen.kill()`` of the driver would leave the real compiler running
    and block the second ``communicate()`` until it finished on its own.  The
    measurement would then report a 120-second timeout after ten minutes.
    """
    if sys.platform == "win32":
        try:
            done = subprocess.run(
                ["taskkill", "/F", "/T", "/PID", str(process.pid)],
                capture_output=True, shell=False, timeout=30)
            if done.returncode == 0:
                return
        except (OSError, subprocess.TimeoutExpired):
            pass
    try:
        process.kill()
    except OSError:
        pass


def compile_profile(gxx: pathlib.Path, flags: list[str], tu: pathlib.Path,
                    include_dirs: list[pathlib.Path], timeout_s: float) -> dict:
    argv = [str(gxx), *flags, *sum((["-I", str(item)] for item in include_dirs), []),
            str(tu)]
    started = time.monotonic()
    process = subprocess.Popen(argv, stdout=subprocess.PIPE,
                               stderr=subprocess.PIPE, shell=False)
    try:
        out, err = process.communicate(timeout=timeout_s)
        rc = process.returncode
        error = None
    except subprocess.TimeoutExpired:
        kill_process_tree(process)
        out, err = process.communicate()
        rc = None
        error = "timeout after %.0fs" % timeout_s
    stderr = (err or b"").decode("utf-8", "replace")
    duration = time.monotonic() - started
    first = None
    for line in stderr.splitlines():
        stripped = line.strip()
        if stripped.endswith("error") or ": error:" in stripped:
            first = stripped
            break
    return {
        "rc": rc,
        "status": "pass" if rc == 0 else "fail",
        "error": error,
        "first_error": first,
        "stderr_tail": "\n".join(stderr.strip().splitlines()[-4:]),
        "duration_s": round(duration, 3),
        "argv": argv,
    }


# Compiler signatures of the catalogue's P3 baseline defects.  A generated row
# that fails with the same signature as its root's catalogue row is a new
# instance of that row, not an explanation-free failure.  The table is keyed on
# the *diagnostic*, so a new input that triggers the same defect classifies the
# same way, exactly like compare.ALLOWED_STRICTER.
BASELINE_SIGNATURES = [
    ("integer constant is so large that it is unsigned", "R1", "CR-05"),
    ("'INF' was not declared in this scope", "R1", "CR-02"),
    ("'Infinity' was not declared in this scope", "R1", "CR-02"),
    ("'NAN' was not declared in this scope", "R1", "CR-02"),
    ("'nan' was not declared in this scope", "R1", "CR-02"),
    ("conflicts with a previous declaration", "R4", "CR-03"),
    ("'::encode' is not a type", "R4", "CR-04"),
    ("'::decode' is not a type", "R4", "CR-04"),
    ("redeclared as different kind of entity", "R4", "CR-09"),
    ("expected unqualified-id before numeric constant", "R4", "CR-10"),
]


def classify_failure(row: dict, profile: str, verdict: dict) -> str:
    if verdict.get("error"):
        return "timeout"
    message = (verdict.get("stderr_tail") or "") + " " + (
        verdict.get("first_error") or "")
    if "No such file" in message and ".pb.hpp" in message:
        return "missing-dependency-header"
    if row.get("cr") in KNOWN_P3_ROWS and profile in DEFAULT_PROFILES:
        return "known-p3-row"
    for marker, root, cr in BASELINE_SIGNATURES:
        if marker in message and row.get("root") == root:
            return "known-root-instance:%s" % cr
    return "unexplained"


def process_row(row: dict, args, run_dir: pathlib.Path,
                lite_codegen: pathlib.Path | None) -> dict:
    case_dir = run_dir / row["id"]
    case_dir.mkdir(parents=True, exist_ok=True)
    result: dict = {
        "id": row["id"], "kind": row["kind"], "source": row["source"],
        "cr": row.get("cr"), "root": row.get("root"),
        "input": row.get("input"), "target": row.get("target"),
    }
    item = run.run_case(row, run_dir, args.codegen.resolve(),
                        args.protoc.resolve(), args.timeout,
                        args.child_env_overrides)
    p1 = item.get("p1") or {}
    result["codegen_accept"] = p1.get("codegen_accept")
    if p1.get("codegen_accept") is not True:
        result["status"] = "skipped-not-accepted"
        return result

    # The row's own invocation writes the target header.  It is the header P3
    # is about; the descriptor closure below only supplies its dependencies.
    logical = item.get("logical_name") or row.get("target") or ""
    row_out = case_dir / "codegen"
    header = row_out / (fds.header_stem(logical) + ".pb.hpp")
    if not header.is_file():
        matches = sorted(row_out.rglob(fds.header_stem(logical) + ".pb.hpp"))
        header = matches[0] if matches else header
    result["header"] = relative(header) if header.is_file() else None
    result["header_sha256"] = (
        runner.sha256_file(header) if header.is_file() else None)

    if row.get("p3_applicable") is False:
        # A generator-stress fixture (for example the 12 000-message by-value
        # chain) can be an accepted P1/P8 input without being a compile
        # fixture: the header is 9.5 MB and the compiler's own stack, not the
        # generated C++, is the limit.  The row declares that in its sidecar.
        result["status"] = "not-a-compile-fixture"
        result["reason"] = row.get("p3_note") or (
            "declared not a P3 compile fixture")
        return result

    out_dir = case_dir / "closure"
    closure = generate_closure(row, case_dir, args.codegen.resolve(), out_dir,
                               child_environment(args.child_env_overrides))
    result["closure"] = closure
    result["profiles"] = {}
    if not header.is_file():
        result["status"] = "skipped-no-header"
        return result

    tu = case_dir / "tu.cpp"
    # The header may live below a logical subdirectory; the include root is the
    # directory it was written to, and the closure directory supplies the
    # dependency headers the header contract asks the caller to generate.
    tu.write_text('#include "%s"\n' % header.name, encoding="utf-8",
                  newline="\n")
    include_dirs = [header.parent, out_dir, REPO / "include"]
    for profile in args.profiles:
        verdict = compile_profile(args.gxx.resolve(), PROFILE_FLAGS[profile],
                                  tu, include_dirs, args.compile_timeout)
        verdict["classification"] = (
            "pass" if verdict["rc"] == 0
            else classify_failure(row, profile, verdict))
        result["profiles"][profile] = verdict

    if lite_codegen and row["kind"] == "descriptor":
        lite_dir = case_dir / "closure-lite"
        lite_closure = generate_closure(row, case_dir, lite_codegen, lite_dir,
                                        child_environment(
                                            args.child_env_overrides))
        lite_header = header_for(lite_dir, lite_closure.get("target") or "")
        entry: dict = {"applicable": True, "closure_failures":
                       lite_closure.get("failures", [])}
        if lite_header.is_file():
            lite_sha = runner.sha256_file(lite_header)
            entry["header_sha256"] = lite_sha
            entry["identical_to_probe"] = lite_sha == result["header_sha256"]
            if entry["identical_to_probe"]:
                entry["status"] = "identity"
            else:
                lite_tu = case_dir / "tu-lite.cpp"
                lite_tu.write_text(
                    '#include "%s"\n' % lite_header.relative_to(
                        lite_dir).as_posix(),
                    encoding="utf-8", newline="\n")
                entry["profiles"] = {}
                for profile in args.profiles:
                    verdict = compile_profile(
                        args.gxx.resolve(), PROFILE_FLAGS[profile], lite_tu,
                        [lite_dir, REPO / "include"], args.compile_timeout)
                    verdict["classification"] = (
                        "pass" if verdict["rc"] == 0
                        else classify_failure(row, profile, verdict))
                    entry["profiles"][profile] = verdict
        else:
            entry["status"] = "no-header"
        result["lite"] = entry
    else:
        result["lite"] = {
            "applicable": False,
            "reason": "source row: the lite build has no .proto loader",
        }
    result["status"] = "measured"
    return result


def summarise(results: list[dict], rows: list[dict], run_dir: pathlib.Path,
              args, duration_s: float, lite_codegen: pathlib.Path | None) -> dict:
    def failures_of(item: dict) -> list[dict]:
        found = []
        for profile, verdict in (item.get("profiles") or {}).items():
            if verdict.get("rc") != 0:
                found.append({
                    "id": item["id"], "profile": profile,
                    "classification": verdict.get("classification"),
                    "first_error": verdict.get("first_error"),
                })
        return found

    failures = [entry for item in results for entry in failures_of(item)]
    lite_failures = []
    for item in results:
        lite = item.get("lite") or {}
        for profile, verdict in (lite.get("profiles") or {}).items():
            if verdict.get("rc") != 0:
                lite_failures.append({
                    "id": item["id"], "profile": "lite/" + profile,
                    "classification": verdict.get("classification"),
                    "first_error": verdict.get("first_error"),
                })
    unexplained = [entry for entry in failures + lite_failures
                   if entry["classification"] in ("unexplained", "timeout")
                   or entry["classification"] == "missing-dependency-header"]
    known = [entry for entry in failures + lite_failures
             if entry["classification"] == "known-p3-row"
             or entry["classification"].startswith("known-root-instance")]
    measured = [item for item in results if item["status"] == "measured"]
    lite_rows = [item for item in results if (item.get("lite") or {}).get("applicable")]
    lite_identity = [item for item in lite_rows
                     if (item.get("lite") or {}).get("status") == "identity"]
    setup_gaps = [item for item in results
                  if item["status"].startswith("skipped")]
    not_compile = [item for item in results
                   if item["status"] == "not-a-compile-fixture"]
    summary = {
        "schema": 1,
        "step": "B2b",
        "property": "P3",
        "run_id": run_dir.name,
        "started_at": args._started_at,
        "finished_at": dt.datetime.now().astimezone().isoformat(timespec="seconds"),
        "duration_s": round(duration_s, 2),
        "command": args._command,
        "cases_requested": args.cases,
        "cases_selected": len(results),
        "cases_accepted": sum(1 for item in results
                              if item.get("codegen_accept") is True),
        "cases_measured": len(measured),
        "cases_skipped": len(setup_gaps),
        "profiles": list(args.profiles),
        "compile_failures": len(failures),
        "known_baseline": len(known),
        "unexplained": len(unexplained),
        "unexplained_detail": unexplained,
        "known_detail": known,
        "lite": {
            "applicable_rows": len(lite_rows),
            "identity_rows": len(lite_identity),
            "compile_failures": len(lite_failures),
            "failures_detail": lite_failures,
            "codegen": str(lite_codegen) if lite_codegen else None,
            "codegen_sha256": (
                runner.sha256_file(lite_codegen)
                if lite_codegen and lite_codegen.is_file() else None),
            "note": ("a source row is not applicable: the lite build has no "
                     ".proto loader"),
        },
        "setup_gaps": [{"id": item["id"], "status": item["status"],
                        "closure": item.get("closure")} for item in setup_gaps],
        "not_compile_fixtures": [
            {"id": item["id"], "reason": item.get("reason"),
             "header": item.get("header"),
             "header_sha256": item.get("header_sha256")}
            for item in not_compile],
        "tools": {
            "gxx": str(args.gxx),
            "gxx_version": compiler_first_line(args.gxx, "--version"),
            "gxx_target": compiler_first_line(args.gxx, "-dumpmachine"),
            "codegen": str(args.codegen.resolve()),
            "codegen_sha256": runner.sha256_file(args.codegen.resolve()),
            "protoc": str(args.protoc.resolve()),
        },
        "environment": {"python": sys.version.split()[0],
                        "platform": platform.platform(),
                        "measured_path_isolated": bool(
                            args.child_env_overrides)},
        "cases": results,
    }
    return summary


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--cases", type=int, default=0,
                        help="0 runs the whole corpus")
    parser.add_argument("--seed", type=int, default=1)
    parser.add_argument("--corpus", type=pathlib.Path,
                        default=run.DEFAULT_CORPUS)
    parser.add_argument("--protoc", type=pathlib.Path,
                        default=run.DEFAULT_PROTOC)
    parser.add_argument("--codegen", type=pathlib.Path,
                        default=run.DEFAULT_CODEGEN)
    parser.add_argument("--lite-codegen", type=pathlib.Path, default=None,
                        help="parser-free codegen.exe for the lite profile")
    parser.add_argument("--gxx", type=pathlib.Path, default=DEFAULT_GXX)
    parser.add_argument("--profile", action="append", choices=sorted(PROFILE_FLAGS),
                        help="compile profile to measure; repeatable "
                             "(default: %s)" % " ".join(DEFAULT_PROFILES))
    parser.add_argument("--jobs", type=int, default=8)
    parser.add_argument("--timeout", type=float, default=10.0)
    parser.add_argument("--compile-timeout", type=float, default=120.0)
    parser.add_argument("--out", type=pathlib.Path, default=None,
                        help="run directory, or a .json file for the summary "
                             "(the per-case tree still goes to runs/)")
    parser.add_argument("--quiet", action="store_true")
    args = parser.parse_args()

    args.protoc = runner.resolve_tool(args.protoc)
    args.codegen = runner.resolve_tool(args.codegen)
    if args.lite_codegen is not None:
        args.lite_codegen = runner.resolve_tool(args.lite_codegen)
    args.gxx = runner.resolve_tool(args.gxx)

    args.profiles = []
    for name in (args.profile or DEFAULT_PROFILES):
        if name not in args.profiles:
            args.profiles.append(name)
    # A legacy profile runs inside an activated old toolchain; its bin
    # directory must not decide which C++ runtime the measured codegen loads.
    args.child_env_overrides = (
        legacy_child_env(args.gxx)
        if any(name.startswith("legacy-") for name in args.profiles) else None)

    started = time.monotonic()
    args._started_at = dt.datetime.now().astimezone().isoformat(timespec="seconds")
    args._command = [sys.executable] + sys.argv
    for label, path in (("protoc", args.protoc), ("codegen", args.codegen),
                        ("g++", args.gxx)):
        if not path.is_file():
            print("%s not found: %s" % (label, path), file=sys.stderr)
            return 2
    lite_codegen = args.lite_codegen
    if lite_codegen is not None and not lite_codegen.is_file():
        print("lite codegen not found: %s" % lite_codegen, file=sys.stderr)
        return 2

    rows = run.load_rows(args.corpus)
    selected, _not_comparable, note = run.select_rows(rows, args.cases, args.seed)
    run_id = dt.datetime.now().strftime("p3-%Y%m%d-%H%M%S")
    # A named .json target is the summary file, not a run tree: the per-case
    # artifacts still need a directory, and the summary is written once.
    out_file = args.out.resolve() if args.out and args.out.suffix.lower() == ".json" else None
    run_dir = ((HERE / "runs" / run_id) if out_file
               else (args.out or (HERE / "runs" / run_id))).resolve()
    run_dir.mkdir(parents=True, exist_ok=True)
    print("run: %s" % run_dir)
    print("profiles: %s" % ", ".join(args.profiles))
    if args.child_env_overrides:
        print("measured tools: legacy toolchain removed from PATH")
    print("selection: %s" % note)
    print("codegen: %s" % args.codegen)
    print("g++: %s" % args.gxx)

    results = []
    with concurrent.futures.ThreadPoolExecutor(max_workers=max(1, args.jobs)) as pool:
        futures = {
            pool.submit(process_row, row, args, run_dir, lite_codegen): row
            for row in selected
        }
        for index, future in enumerate(
                concurrent.futures.as_completed(futures), start=1):
            row = futures[future]
            try:
                item = future.result()
            except Exception as error:  # keep the matrix going; record the gap
                item = {"id": row["id"], "status": "harness-error",
                        "error": "%s: %s" % (type(error).__name__, error)}
            results.append(item)
            if not args.quiet:
                profiles = item.get("profiles") or {}
                state = ",".join(
                    "%s=%s" % (name, verdict.get("status"))
                    for name, verdict in profiles.items()) or item["status"]
                print("[%3d/%3d] %-56s %s" % (
                    index, len(selected), row["id"], state))

    results.sort(key=lambda item: item["id"])
    summary = summarise(results, rows, run_dir, args, time.monotonic() - started,
                        lite_codegen)
    write_json(run_dir / "p3-summary.json", summary)
    # `p3-summary.json` next to the driver is the pinned B2b baseline.  Only an
    # unnamed default-profile run may replace it; a named file or a legacy
    # profile is separate evidence.
    if out_file is not None:
        write_json(out_file, summary)
    elif args.profiles == DEFAULT_PROFILES:
        write_json(HERE / "p3-summary.json", summary)

    print()
    print("accepted / measured: %d / %d (skipped %d)" % (
        summary["cases_accepted"], summary["cases_measured"],
        summary["cases_skipped"]))
    print("compile failures:    %d (known baseline %d, unexplained %d)" % (
        summary["compile_failures"], summary["known_baseline"],
        summary["unexplained"]))
    print("lite:                %d rows, %d identical headers, %d failures" % (
        summary["lite"]["applicable_rows"], summary["lite"]["identity_rows"],
        summary["lite"]["compile_failures"]))
    if summary["not_compile_fixtures"]:
        print("not compile fixtures: %d (%s)" % (
            len(summary["not_compile_fixtures"]),
            ", ".join(item["id"] for item in summary["not_compile_fixtures"])))
    print("duration:            %.1fs" % summary["duration_s"])
    print("summary:             %s" % (
        out_file if out_file is not None else run_dir / "p3-summary.json"))
    for entry in summary["unexplained_detail"]:
        print("  UNEXPLAINED %s %s: %s" % (
            entry["id"], entry["profile"], entry["first_error"]))
    return 1 if summary["unexplained"] else 0


if __name__ == "__main__":
    sys.exit(main())
